#!/usr/bin/env node
// Build the browser extension (Chrome + Firefox, Manifest V3) from the same
// source files the userscript uses. Nothing in the Devtools_*.js sources is
// forked: the @require list in Devtools.user.js is the single source of truth
// for WHICH files load and in WHAT order, and this script bundles them into one
// main-world content script with GM_* / unsafeWindow shims around them.
//
// Usage (or use ./build.sh, which wraps this):
//   node build-extension.mjs                    # all targets -> dist/chrome/, dist/firefox/
//   node build-extension.mjs chrome             # one target
//   node build-extension.mjs firefox --zip      # + dist/devtools-sidebar-<version>-firefox.zip (needs `zip`)
//   node build-extension.mjs --watch            # rebuild on every source change
//
// Load unpacked: chrome://extensions → Developer mode → Load unpacked → dist/chrome
//                about:debugging#/runtime/this-firefox → Load Temporary Add-on → dist/firefox/manifest.json

import { readFileSync, writeFileSync, mkdirSync, rmSync, cpSync, existsSync, watch } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { execFileSync } from 'node:child_process';

const dir = dirname(fileURLToPath(import.meta.url));
const SRC = join(dir, 'extension');
const DIST = join(dir, 'dist');
const read = p => readFileSync(join(dir, p), 'utf8');

const TARGETS = ['chrome', 'firefox'];
const args = process.argv.slice(2);
const unknown = args.filter(a => !a.startsWith('--') && !TARGETS.includes(a) && a !== 'all');
if (unknown.length || args.includes('--help')) {
  console.log('Usage: node build-extension.mjs [chrome|firefox|all] [--zip] [--watch]');
  process.exit(unknown.length ? 1 : 0);
}
const picked = args.filter(a => TARGETS.includes(a));
const targets = picked.length ? picked : TARGETS;
const ZIP = args.includes('--zip');
const WATCH = args.includes('--watch');

// ─── Bundle ───────────────────────────────────────────────────────────────────
const CM_PREFIX = /^https:\/\/cdn\.jsdelivr\.net\/npm\/codemirror@[\d.]+\//;
const GH_PREFIX = /^https:\/\/cdn\.jsdelivr\.net\/gh\/[^/]+\/[^@]+@v[\d.]+\//;
const stripSourceMap = code => code.replace(/^\/\/# sourceMappingURL=.*$/gm, '');

function readEntry() {
  const entry = read('Devtools.user.js');
  const header = key => [...entry.matchAll(new RegExp(`//\\s*@${key}\\s+(.+)`, 'g'))].map(m => m[1].trim());
  const version = header('version')[0];
  if (!/^\d+\.\d+\.\d+$/.test(version || '')) throw new Error(`Bad @version in Devtools.user.js: ${version}`);
  const requires = header('require').map(url => {
    if (CM_PREFIX.test(url)) return { kind: 'codemirror', path: join('extension', 'vendor', 'codemirror', url.replace(CM_PREFIX, '')) };
    if (GH_PREFIX.test(url)) return { kind: 'source', path: url.replace(GH_PREFIX, '') };
    // Local dev pins (http://127.0.0.1:8421/<file>) resolve to the repo file too.
    const local = url.match(/^https?:\/\/(?:127\.0\.0\.1|localhost)(?::\d+)?\/(.+)$/);
    if (local) return { kind: 'source', path: local[1] };
    throw new Error(`Don't know how to bundle @require ${url}`);
  });
  for (const r of requires) {
    if (!existsSync(join(dir, r.path))) throw new Error(`Missing ${r.path} (vendor CodeMirror files live in extension/vendor/codemirror/)`);
  }
  return { version, description: header('description')[0], requires };
}

function buildBundle(version, requires) {
  const cmCode = requires.filter(r => r.kind === 'codemirror').map((r, i) =>
    i === 0
      // The core UMD attaches to `this` when there's no module system; call it on
      // a private object so the page never gets (or clobbers) a CodeMirror global.
      ? `// ${r.path}\n(function () {\n${stripSourceMap(read(r.path))}\n}).call(__dtCM);\nconst CodeMirror = __dtCM.CodeMirror;`
      // Addons fall through their UMD to `mod(CodeMirror)` — the local above.
      : `// ${r.path}\n${stripSourceMap(read(r.path))}`
  ).join('\n\n');
  const srcCode = requires.filter(r => r.kind === 'source')
    .map(r => `// ─── ${r.path} ${'─'.repeat(Math.max(0, 70 - r.path.length))}\n${read(r.path)}`).join('\n\n');

  return `// DevTools Sidebar v${version} — extension bundle. GENERATED by build-extension.mjs; edit the sources, not this file.
(function () {
  if (window.top !== window.self) return;
  if (window.__dtSidebarExtension) return; // guard against double injection
  Object.defineProperty(window, '__dtSidebarExtension', { value: true });

  // ─── Storage bridge (see extension/bridge.js) ──────────────────────────────
  let port = null, cache = null, booted = false;
  const listeners = {};
  const fetchWaiters = new Map();
  let fetchSeq = 0;
  const clone = v => (v === undefined ? v : JSON.parse(JSON.stringify(v)));
  window.addEventListener('message', e => {
    if (e.source !== window || !e.data || e.data.__dtExtBridge !== 'port' || !e.ports[0]) return;
    e.stopImmediatePropagation();
    // Always adopt the newest port — the bridge re-hands one off if our hello
    // crossed its first handoff, and closes the old one.
    port = e.ports[0];
    port.onmessage = onBridgeMessage;
  }, true);
  window.postMessage({ __dtExtBridge: 'hello' }, '*');

  function onBridgeMessage(e) {
    const m = e.data || {};
    if (m.type === 'init') {
      if (!booted) { cache = m.data || {}; booted = true; start(); }
    } else if (m.type === 'changed' && cache) {
      for (const [key, newValue] of Object.entries(m.changes || {})) {
        const oldValue = cache[key];
        cache[key] = newValue;
        (listeners[key] || []).forEach(cb => { try { cb(key, clone(oldValue), clone(newValue), true); } catch (err) { console.warn('[DevTools] change listener failed', err); } });
      }
    } else if (m.type === 'fetchResult') {
      const w = fetchWaiters.get(m.id);
      if (w) { fetchWaiters.delete(m.id); m.ok ? w.resolve(m.data) : w.reject(new Error(m.error || 'fetch failed')); }
    } else if (m.type === 'toggle') {
      const r = document.getElementById('dt-host');
      const tab = r && r.shadowRoot && r.shadowRoot.getElementById('dt-tab');
      if (tab) tab.click();
    }
  }

  function start() {
    // Shadow page-level module systems so CodeMirror's UMD wrappers never
    // register with a site's own AMD loader / CommonJS shim.
    var define, exports, module, require;
    const unsafeWindow = window;
    function GM_getValue(key, fallback) { return Object.prototype.hasOwnProperty.call(cache, key) ? clone(cache[key]) : fallback; }
    function GM_setValue(key, value) {
      cache[key] = clone(value);
      if (port) port.postMessage({ type: 'set', key, value: clone(value) });
    }
    function GM_addValueChangeListener(key, cb) { (listeners[key] ||= []).push(cb); return key; }
    // Cross-origin fetch through the extension (used by the Smart dark engine to
    // read stylesheets/icons the page's CORS rules would hide). kind: 'text' | 'dataurl'.
    function DT_extFetch(url, kind) {
      return new Promise((resolve, reject) => {
        if (!port) return reject(new Error('extension bridge not connected'));
        const id = ++fetchSeq;
        fetchWaiters.set(id, { resolve, reject });
        port.postMessage({ type: 'fetch', id, url, kind });
        setTimeout(() => { if (fetchWaiters.delete(id)) reject(new Error('timeout')); }, 20000);
      });
    }
    const __dtCM = {};

${cmCode}

${srcCode}
  }
})();
`;
}

// ─── Manifest (per target) ────────────────────────────────────────────────────
// Each store flags the other browser's keys ("Unrecognized manifest key"), so
// every target gets only what it understands.
function buildManifest(target, version, description) {
  const MATCHES = ['http://*/*', 'https://*/*'];
  const manifest = {
    manifest_version: 3,
    name: 'DevTools Sidebar',
    version,
    description,
    icons: { 16: 'icons/icon16.png', 32: 'icons/icon32.png', 48: 'icons/icon48.png', 128: 'icons/icon128.png' },
    action: { default_title: 'Toggle DevTools Sidebar', default_icon: { 16: 'icons/icon16.png', 32: 'icons/icon32.png' } },
    permissions: ['storage'],
    host_permissions: MATCHES,
    background: target === 'chrome' ? { service_worker: 'background.js' } : { scripts: ['background.js'] },
    content_scripts: [
      { matches: MATCHES, js: ['bridge.js'], run_at: 'document_start', all_frames: false },
      // world: MAIN needs Chrome 111+ / Firefox 128+.
      { matches: MATCHES, js: ['devtools.js'], run_at: 'document_start', all_frames: false, world: 'MAIN' },
    ],
  };
  if (target === 'chrome') manifest.minimum_chrome_version = '111';
  if (target === 'firefox') manifest.browser_specific_settings = { gecko: { id: 'devtools-sidebar@mrnosferatu', strict_min_version: '128.0' } };
  return manifest;
}

// ─── Build ────────────────────────────────────────────────────────────────────
function build() {
  const started = Date.now();
  const { version, description, requires } = readEntry();
  const bundle = buildBundle(version, requires);
  for (const target of targets) {
    const out = join(DIST, target);
    rmSync(out, { recursive: true, force: true });
    mkdirSync(out, { recursive: true });
    writeFileSync(join(out, 'manifest.json'), JSON.stringify(buildManifest(target, version, description), null, 2) + '\n');
    writeFileSync(join(out, 'devtools.js'), bundle);
    cpSync(join(SRC, 'bridge.js'), join(out, 'bridge.js'));
    cpSync(join(SRC, 'background.js'), join(out, 'background.js'));
    mkdirSync(join(out, 'icons'));
    for (const s of [16, 32, 48, 128]) cpSync(join(SRC, 'icons', `icon${s}.png`), join(out, 'icons', `icon${s}.png`));

    let line = `  ${target.padEnd(8)} → dist/${target}/`;
    if (ZIP) {
      const zipName = `devtools-sidebar-${version}-${target}.zip`;
      rmSync(join(DIST, zipName), { force: true });
      execFileSync('zip', ['-qr', join(DIST, zipName), '.'], { cwd: out, stdio: 'inherit' });
      line += `  +  dist/${zipName}`;
    }
    console.log(line);
  }
  console.log(`Built DevTools Sidebar v${version} (${requires.length} files, ${(bundle.length / 1024).toFixed(0)} KB bundle) in ${Date.now() - started} ms`);
}

try { build(); } catch (e) { console.error(`Build failed: ${e.message}`); if (!WATCH) process.exit(1); }

if (WATCH) {
  // Rebuild when a bundled source, the entry script, or extension/ changes.
  // Editors often emit several events per save, so debounce.
  let timer = null;
  const schedule = file => {
    clearTimeout(timer);
    timer = setTimeout(() => {
      console.log(`\n${new Date().toLocaleTimeString()} ${file} changed — rebuilding`);
      try { build(); } catch (e) { console.error(`Build failed: ${e.message}`); }
    }, 150);
  };
  watch(dir, (_, file) => { if (file && /^Devtools.*\.js$/.test(file)) schedule(file); });
  watch(SRC, { recursive: true }, (_, file) => { if (file) schedule(join('extension', file)); });
  console.log('Watching for changes (Ctrl+C to stop). Reload the extension in the browser after each rebuild.');
}
